package မြန်မာ.ကိုယ်ပိုင်;
/** စက်နှိုးချိန် ရွေးထားသော အရွယ်ရှိ ကိုယ်ပိုင်အူတိုင် RGB32 ပုံသိုလှောင်မျက်နှာပြင်။ */
public final class မျက်နှာပြင် {
    private မျက်နှာပြင်() {}
    public static int အနံတန်ဖိုး() { int တန်ဖိုး = အူတိုင်တန်ဖိုး.မျက်နှာပြင်အနံ(); if (တန်ဖိုး < 0) throw new အခြေအနေခြွင်းချက်("ပုံသိုလှောင်မျက်နှာပြင် မရှိပါ"); return တန်ဖိုး; }
    public static int အမြင့်တန်ဖိုး() { int တန်ဖိုး = အူတိုင်တန်ဖိုး.မျက်နှာပြင်အမြင့်(); if (တန်ဖိုး < 0) throw new အခြေအနေခြွင်းချက်("ပုံသိုလှောင်မျက်နှာပြင် မရှိပါ"); return တန်ဖိုး; }
    public static void စတုဂံ(int အလျားတည်နေရာ, int ဒေါင်လိုက်တည်နေရာ, int အကျယ်အဝန်း, int အမြင့်တန်ဖိုး, int အရောင်တန်ဖိုး) {
        if (အလျားတည်နေရာ < 0 || ဒေါင်လိုက်တည်နေရာ < 0 || အကျယ်အဝန်း < 0 || အမြင့်တန်ဖိုး < 0 || အလျားတည်နေရာ > အနံတန်ဖိုး() || ဒေါင်လိုက်တည်နေရာ > အမြင့်တန်ဖိုး() || အကျယ်အဝန်း > အနံတန်ဖိုး() - အလျားတည်နေရာ || အမြင့်တန်ဖိုး > အမြင့်တန်ဖိုး() - ဒေါင်လိုက်တည်နေရာ) throw new မမှန်ကန်ပေးအချက်ခြွင်းချက်("မျက်နှာပြင်နယ်နိမိတ်");
        if (အူတိုင်တန်ဖိုး.စတုဂံ(အလျားတည်နေရာ, ဒေါင်လိုက်တည်နေရာ, အကျယ်အဝန်း, အမြင့်တန်ဖိုး, အရောင်တန်ဖိုး) < 0) throw new အခြေအနေခြွင်းချက်("ပုံသိုလှောင်မျက်နှာပြင် မရှိပါ");
    }
    public static void အချက်ဖျက်(int အရောင်တန်ဖိုး) { စတုဂံ(0, 0, အနံတန်ဖိုး(), အမြင့်တန်ဖိုး(), အရောင်တန်ဖိုး); }
    public static void စောင့်() { if (အူတိုင်တန်ဖိုး.ပုံစောင့်() < 0) throw new အခြေအနေခြွင်းချက်("အပြန်အလှန် အဝင်လိုအပ်သည်"); }
}
